/* Capability cockpit activity projection.
 * Source of truth for live runs remains dashboard/js/run-control.js.
 * Receipt history must never be promoted to an active operation.
 */

const ACTIVE_STATES = new Set(['requested', 'approved', 'starting', 'running', 'waiting', 'stopping']);
const TERMINAL_STATES = new Set(['stopped', 'completed', 'failed', 'skipped', 'aborted', 'disconnected']);

function sanitizeRun(run) {
  if (!run || typeof run !== 'object') return null;
  return {
    runId: String(run.runId || ''),
    kind: String(run.kind || 'run').slice(0, 80),
    state: String(run.state || 'unknown').slice(0, 32),
    summary: String(run.summary || '').slice(0, 240),
    updatedAt: run.updatedAt ? String(run.updatedAt) : null,
    endedAt: run.endedAt ? String(run.endedAt) : null,
    source: String(run.source || 'unknown').slice(0, 32)
  };
}

/**
 * @param {{ feedStatus: string, activeRun?: object|null, latestRun?: object|null }} input
 * @returns {object} privacy-safe activity projection for the capability cockpit
 */
export function projectCockpitActivity(input = {}) {
  const feedStatus = String(input.feedStatus || 'NOT_CONNECTED');
  const guard = 'RECEIPT_HISTORY_IS_NOT_LIVE_ACTIVITY';

  if (feedStatus !== 'CONNECTED') {
    return {
      feed_status: feedStatus === 'UNKNOWN' ? 'UNKNOWN' : 'NOT_CONNECTED',
      activity_class: feedStatus === 'UNKNOWN' ? 'UNKNOWN' : 'NOT_CONNECTED',
      headline: feedStatus === 'UNKNOWN'
        ? 'Run-feed status unknown'
        : 'Run feed not connected on this page',
      detail: 'Active operations cannot be certified here. Historical receipts below are not live activity or field outcomes.',
      active_run: null,
      latest_terminal_run: null,
      conflation_guard: guard
    };
  }

  const active = sanitizeRun(input.activeRun);
  if (active && ACTIVE_STATES.has(active.state)) {
    return {
      feed_status: 'CONNECTED',
      activity_class: 'ACTIVE',
      headline: `${active.kind} is ${active.state}`,
      detail: active.summary || 'Dashboard run-control reports an active operation. This is independent of receipt history.',
      active_run: active,
      latest_terminal_run: null,
      conflation_guard: guard
    };
  }

  const latest = sanitizeRun(input.latestRun);
  if (latest && TERMINAL_STATES.has(latest.state)) {
    return {
      feed_status: 'CONNECTED',
      activity_class: latest.state === 'disconnected' ? 'DISCONNECTED' : 'HISTORICAL_TERMINAL',
      headline: `${latest.kind} ended as ${latest.state}`,
      detail: 'This is terminal run-control history on the connected feed, not proof that work is running and not a field outcome.',
      active_run: null,
      latest_terminal_run: latest,
      conflation_guard: guard
    };
  }

  return {
    feed_status: 'CONNECTED',
    activity_class: 'UNKNOWN',
    headline: 'No active dashboard run observed',
    detail: 'The run feed is connected, but no current or terminal run is available on this page. Do not infer activity from receipt timestamps.',
    active_run: null,
    latest_terminal_run: null,
    conflation_guard: guard
  };
}

export const COCKPIT_ACTIVITY_ACTIVE_STATES = ACTIVE_STATES;
export const COCKPIT_ACTIVITY_TERMINAL_STATES = TERMINAL_STATES;

#!/usr/bin/env node
'use strict';
/*
 * Offline contract for cockpit activity vs receipt-history separation.
 * Run from any cwd: node dashboard/test_capability_activity.js
 */
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { pathToFileURL } = require('node:url');

const root = path.resolve(__dirname);
const html = fs.readFileSync(path.join(root, 'capabilities.html'), 'utf8');
const cockpit = fs.readFileSync(path.join(root, 'js', 'capability-cockpit.js'), 'utf8');
const activityUrl = pathToFileURL(path.join(root, 'js', 'capability-activity.js')).href;

(async () => {
  const { projectCockpitActivity } = await import(activityUrl);

  const absent = projectCockpitActivity({ feedStatus: 'NOT_CONNECTED' });
  assert.equal(absent.activity_class, 'NOT_CONNECTED');
  assert.equal(absent.active_run, null);
  assert.equal(absent.conflation_guard, 'RECEIPT_HISTORY_IS_NOT_LIVE_ACTIVITY');

  const unknownFeed = projectCockpitActivity({ feedStatus: 'UNKNOWN' });
  assert.equal(unknownFeed.activity_class, 'UNKNOWN');

  const active = projectCockpitActivity({
    feedStatus: 'CONNECTED',
    activeRun: {
      runId: 'r1',
      kind: 'Network probe',
      state: 'running',
      summary: '2 target(s)',
      source: 'relay-server',
      updatedAt: '2026-11-03T12:00:00Z'
    }
  });
  assert.equal(active.activity_class, 'ACTIVE');
  assert.equal(active.active_run.state, 'running');
  assert.equal(active.latest_terminal_run, null);

  const terminal = projectCockpitActivity({
    feedStatus: 'CONNECTED',
    latestRun: {
      runId: 'r2',
      kind: 'Network probe',
      state: 'completed',
      summary: 'finished',
      source: 'ui',
      endedAt: '2026-11-03T12:05:00Z'
    }
  });
  assert.equal(terminal.activity_class, 'HISTORICAL_TERMINAL');
  assert.equal(terminal.active_run, null);
  assert.equal(terminal.latest_terminal_run.state, 'completed');

  const disconnected = projectCockpitActivity({
    feedStatus: 'CONNECTED',
    latestRun: { runId: 'r3', kind: 'Network probe', state: 'disconnected', summary: 'lost' }
  });
  assert.equal(disconnected.activity_class, 'DISCONNECTED');

  const idle = projectCockpitActivity({ feedStatus: 'CONNECTED' });
  assert.equal(idle.activity_class, 'UNKNOWN');
  assert.match(idle.detail, /Do not infer activity from receipt timestamps/);

  for (const id of ['activity-panel', 'activity-headline', 'activity-detail', 'activity-class']) {
    assert.ok(html.includes('id="' + id + '"'), 'missing activity UI anchor: ' + id);
  }
  assert.match(cockpit, /projectCockpitActivity/, 'cockpit must consume the activity projector');
  assert.match(cockpit, /RECEIPT_HISTORY_IS_NOT_LIVE_ACTIVITY/, 'conflation guard must remain visible');
  assert.match(cockpit, /NOT_CONNECTED/, 'absent run feed must fail closed');
  assert.ok(!cockpit.includes('innerHTML'), 'no untrusted HTML injection for activity copy');
  assert.ok(!html.includes('last_receipt_at') || html.includes('Historical receipts'),
    'activity copy must keep receipt history conceptually separate');

  console.log('Capability activity contract PASS: NOT_CONNECTED/UNKNOWN/ACTIVE/HISTORICAL_TERMINAL/DISCONNECTED');
})().catch(err => {
  console.error(err);
  process.exit(1);
});

